// ATMlib does not look at the Arduboy sound setting, so we do it here
void sfx(byte i)
{
  if (arduboy.audio.enabled()) ATM.playSfx((const uint8_t *)pgm_read_word(&sfxList[i]), 1);
}

// play a tune (MUSIC_OFF = stop)
void musicPlay(byte id)
{
  musicId = id;
  if (id == MUSIC_OFF) ATM.stop();
  else ATM.play((const uint8_t *)pgm_read_word(&songs[id]));
}

// pick a random in-game tune, a different one than the game before
void musicPickGameTune()
{
  byte t;
  do t = MUSIC_GAME_FIRST + random(MUSIC_GAMES); while (t == gameTune);
  gameTune = t;
}

// called once per frame: the title tune in the menus, the picked tune while playing, a sting at game over
void musicUpdate()
{
  if (gameState == STATE_MENU_JBOX) return;                // the jukebox decides what plays
  byte want = MUSIC_OFF;
  if (arduboy.audio.enabled())
  {
    if (gameState == STATE_GAME_OVER) want = MUSIC_OVER;
    else if (gameState >= STATE_GAME_INIT_LEVEL) want = gameTune;
    else if (gameState != STATE_MENU_INTRO || introLetter > INTRO_LETTERS) want = MUSIC_TITLE;
  }
  if (want != musicId) musicPlay(want);
}

#endif
